require_once "core.php";
require_once "authcheck.php";
require_once "constants.php";
require_once "maia_db.php";

$display_language = get_display_language($euid);
require_once "./locale/$display_language/stats.php";

/*
 * Gebruiker bepalen
 */
$id = (int)$euid;

if (isset($_GET['id'])) {
    $requestedId = filter_var(
        $_GET['id'],
        FILTER_VALIDATE_INT
    );

    if ($requestedId !== false && $requestedId >= 0) {
        if (is_an_administrator($uid)) {
            $id = $requestedId;
        }
    }
}

/*
 * Kleuren uit bestaande configuratie
 */
$chart_colors = get_chart_colors();

/*
 * Afmetingen
 */
$thumb = !empty($_GET['thumb']);

$width  = $thumb ? 400 : 700;
$height = $thumb ? 200 : 500;

/*
 * Statistieken ophalen
 */
$fields = "
    total_suspected_ham_items AS sh,
    total_ham_items AS h,
    total_wl_items AS wl,
    total_bl_items AS bl,
    total_suspected_spam_items AS ss,
    total_spam_items AS s,
    total_fp_items AS fp,
    total_fn_items AS fn,
    total_virus_items AS v,
    total_bad_header_items AS bh,
    total_banned_file_items AS bf,
    total_oversized_items AS os
";

if ($id === 0) {
    $sql = "
        SELECT
            SUM(total_suspected_ham_items) AS sh,
            SUM(total_ham_items) AS h,
            SUM(total_wl_items) AS wl,
            SUM(total_bl_items) AS bl,
            SUM(total_suspected_spam_items) AS ss,
            SUM(total_spam_items) AS s,
            SUM(total_fp_items) AS fp,
            SUM(total_fn_items) AS fn,
            SUM(total_virus_items) AS v,
            SUM(total_bad_header_items) AS bh,
            SUM(total_banned_file_items) AS bf,
            SUM(total_oversized_items) AS os
        FROM maia_stats
    ";

    $sth = $dbh->query($sql);
} else {
    $sql = "
        SELECT $fields
        FROM maia_stats
        WHERE user_id = :id
    ";

    $sth = $dbh->prepare($sql);
    $sth->execute(['id' => $id]);
}

$row = $sth->fetch(PDO::FETCH_ASSOC) ?: [];

/*
 * Statistieken verzamelen.
 * Ook nulwaarden in de legenda tonen.
 */
$data = [];

foreach ($row as $key => $value) {
    $data[$key] = max(0, (float)$value);
}

$total = array_sum($data);

/*
 * Kleurconverter.
 * Ondersteunt hexkleuren en veelgebruikte kleurnamen.
 */
function chartColor($image, $value)
{
    $names = [
        'red'    => '#FF0000',
        'green'  => '#008000',
        'blue'   => '#0000FF',
        'yellow' => '#FFFF00',
        'orange' => '#FFA500',
        'gray'   => '#808080',
        'grey'   => '#808080',
        'white'  => '#FFFFFF',
        'black'  => '#000000',
        'pink'   => '#FFC0CB',
        'purple' => '#800080',
        'cyan'   => '#00FFFF'
    ];

    $value = strtolower(trim((string)$value));

    if (isset($names[$value])) {
        $value = $names[$value];
    }

    $hex = ltrim($value, '#');

    if (strlen($hex) === 3) {
        $hex = $hex[0] . $hex[0]
             . $hex[1] . $hex[1]
             . $hex[2] . $hex[2];
    }

    if (!preg_match('/^[0-9a-f]{6}$/', $hex)) {
        $hex = '999999';
    }

    return imagecolorallocate(
        $image,
        hexdec(substr($hex, 0, 2)),
        hexdec(substr($hex, 2, 2)),
        hexdec(substr($hex, 4, 2))
    );
}

/*
 * Tekst tekenen.
 * Gebruik TrueType indien beschikbaar.
 */
function chartText(
    $image,
    $size,
    $x,
    $y,
    $color,
    $text,
    $font
) {
    if (is_string($font) && is_file($font)) {
        imagettftext(
            $image,
            $size,
            0,
            (int)$x,
            (int)$y,
            $color,
            $font,
            (string)$text
        );
    } else {
        imagestring(
            $image,
            2,
            (int)$x,
            (int)$y - 10,
            (string)$text,
            $color
        );
    }
}

/*
 * Afbeelding aanmaken
 */
$image = imagecreatetruecolor($width, $height);
imageantialias($image, true);

$white = imagecolorallocate($image, 255, 255, 255);
$black = imagecolorallocate($image, 30, 30, 30);
$gray  = imagecolorallocate($image, 130, 130, 130);

imagefill($image, 0, 0, $white);

$font = $chart_font ?? '';

/*
 * Titel
 */
chartText(
    $image,
    $thumb ? 9 : 12,
    15,
    25,
    $black,
    'Mail Stats',
    $font
);

/*
 * Cirkel tekenen
 */
if ($total > 0) {

    if ($thumb) {
        $diameter = 140;
        $centerX = 95;
        $centerY = 112;
    } else {
        $diameter = 330;
        $centerX = 230;
        $centerY = 260;
    }

    /*
     * Begin bovenaan (12 uur).
     * Gebruik een cumulatieve hoek zodat alle
     * segmenten exact op elkaar aansluiten.
     */
    $startAngle = 270.0;
    $cumulative = 0.0;

    $positive = array_filter(
        $data,
        static fn($value) => $value > 0
    );

    $lastKey = array_key_last($positive);

    foreach ($positive as $key => $value) {

        $cumulative += $value;

        $endAngle = ($key === $lastKey)
            ? 630.0
            : 270.0 + ($cumulative / $total) * 360.0;

        $color = chartColor(
            $image,
            $chart_colors[$key] ?? '#999999'
        );

        /*
         * GD accepteert gehele graden.
         * Zeer kleine segmenten kunnen daardoor
         * minder dan één pixel breed zijn.
         */
        $start = (int)round($startAngle);
        $end   = (int)round($endAngle);

        if ($end > $start) {
            imagefilledarc(
                $image,
                $centerX,
                $centerY,
                $diameter,
                $diameter,
                $start,
                $end,
                $color,
                IMG_ARC_PIE
            );
        }

        $startAngle = $endAngle;
    }

    /*
     * Dunne buitenrand
     */
    imageellipse(
        $image,
        $centerX,
        $centerY,
        $diameter,
        $diameter,
        $gray
    );
}

/*
 * Legenda
 */
if ($thumb) {
    $legendX = 190;
    $legendY = 40;
    $lineHeight = 13;
    $fontSize = 6;
    $boxSize = 8;
} else {
    $legendX = 430;
    $legendY = 90;
    $lineHeight = 25;
    $fontSize = 9;
    $boxSize = 12;
}

$i = 0;

foreach ($data as $key => $value) {

    $y = $legendY + ($i * $lineHeight);

    $color = chartColor(
        $image,
        $chart_colors[$key] ?? '#999999'
    );

    /*
     * Kleurvakje
     */
    imagefilledrectangle(
        $image,
        $legendX,
        $y,
        $legendX + $boxSize,
        $y + $boxSize,
        $color
    );

    imagerectangle(
        $image,
        $legendX,
        $y,
        $legendX + $boxSize,
        $y + $boxSize,
        $gray
    );

    /*
     * Percentage
     */
    $percentage = $total > 0
        ? ($value / $total) * 100
        : 0;

    $label = $lang['chart_stats'][$key] ?? $key;

    $text = sprintf(
        '%s (%.1f%%)',
        $label,
        $percentage
    );

    /*
     * Tekst
     */
    chartText(
        $image,
        $fontSize,
        $legendX + $boxSize + 8,
        $y + $boxSize,
        $black,
        $text,
        $font
    );

    $i++;
}

/*
 * Geen gegevens
 */
if ($total <= 0) {
    chartText(
        $image,
        10,
        30,
        80,
        $black,
        'Geen statistieken beschikbaar',
        $font
    );
}

/*
 * PNG naar browser
 */
header('Content-Type: image/png');
header('Cache-Control: no-store, no-cache, must-revalidate');

imagepng($image);
imagedestroy($image);

?>
